 for(const m of all.values()){
  if(m.status==='active'){const {data,receivedAt}=await publicGet('/markets/'+encodeURIComponent(m.ticker)+'/orderbook?depth=1');out.push({...m,quotes:quotes(data),receivedAt,exchangeQuoteTime:null});}
